-- ============================================================
-- RBE · Datos semana actual (auto-generado)
-- Semana: Lunes 20 Jul -> Sabado 25 Jul 2026
-- Hoy: Martes 21 Jul 2026
-- Ejecutar DESPUES del script base (y de otros scripts de demo si ya existen)
-- ============================================================
-- Rangos usados en este script (para no chocar con otras cargas de demo):
--   viajes  : 5000 - 5089
--   pagos   : se calculan dinamicamente abajo
--   tickets : se calculan dinamicamente abajo
-- ============================================================

USE rbe;

SET FOREIGN_KEY_CHECKS = 0;
DELETE FROM ticket        WHERE codigo  BETWEEN 9000 AND 10999;
DELETE FROM pago          WHERE numero  BETWEEN 6000 AND 6999;
DELETE FROM viaje_asiento WHERE viaje   BETWEEN 5000 AND 5089;
DELETE FROM viaje         WHERE numero  BETWEEN 5000 AND 5089;
ALTER TABLE viaje   AUTO_INCREMENT = 5000;
ALTER TABLE pago    AUTO_INCREMENT = 6000;
ALTER TABLE ticket  AUTO_INCREMENT = 9000;
SET FOREIGN_KEY_CHECKS = 1;

-- ============================================================
-- VIAJES SEMANA ACTUAL
-- Estado: 1=Disponible 2=En Ruta 3=Finalizado 4=Cancelado 5=Retrasado
-- ============================================================



-- ============================================================
-- ASIENTOS: todos inician en 0 (sin ocupar)
-- ============================================================
SELECT a.numero, v.numero, 0
FROM viaje v
JOIN asiento a ON a.autobus = v.autobus
WHERE v.numero BETWEEN 5000 AND 5089;


-- ============================================================
-- PAGOS — solo viajes finalizados (lunes completo + martes manana = hoy)
-- ============================================================



-- ============================================================
-- TICKETS — viajes finalizados
-- ============================================================



-- ============================================================
-- MARCAR ASIENTOS OCUPADOS segun tickets
-- ============================================================
UPDATE viaje_asiento va
JOIN ticket t ON t.asiento = va.asiento AND t.viaje = va.viaje
SET va.ocupado = 1
WHERE va.viaje BETWEEN 5000 AND 5089;

-- ============================================================
-- VERIFICACION FINAL
-- ============================================================
SELECT '-- VIAJES --' AS info;
SELECT 'Total viajes semana'  AS descripcion, COUNT(*) AS cantidad FROM viaje  WHERE numero BETWEEN 5000 AND 5089;
SELECT 'Finalizados'          AS descripcion, COUNT(*) AS cantidad FROM viaje  WHERE numero BETWEEN 5000 AND 5089 AND estado=3;
SELECT 'En Ruta'              AS descripcion, COUNT(*) AS cantidad FROM viaje  WHERE numero BETWEEN 5000 AND 5089 AND estado=2;
SELECT 'Disponibles'          AS descripcion, COUNT(*) AS cantidad FROM viaje  WHERE numero BETWEEN 5000 AND 5089 AND estado=1;
SELECT 'Cancelados'           AS descripcion, COUNT(*) AS cantidad FROM viaje  WHERE numero BETWEEN 5000 AND 5089 AND estado=4;
SELECT 'Retrasados'           AS descripcion, COUNT(*) AS cantidad FROM viaje  WHERE numero BETWEEN 5000 AND 5089 AND estado=5;
SELECT '-- TRANSACCIONES --' AS info;
SELECT 'Pagos semana'         AS descripcion, COUNT(*) AS cantidad FROM pago   WHERE numero BETWEEN 6000 AND 6020;
SELECT 'Tickets semana'       AS descripcion, COUNT(*) AS cantidad FROM ticket WHERE codigo  BETWEEN 9000 AND 9188;
SELECT 'TOTAL RECAUDADO SEMANA' AS descripcion, CONCAT('$',FORMAT(SUM(monto),2)) AS monto FROM pago WHERE numero BETWEEN 6000 AND 6020;